package net.civeira.phylax.common.infrastructure.consistency;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import io.quarkus.cache.Cache;
import io.quarkus.cache.runtime.noop.NoOpCache;
import io.smallrye.mutiny.Uni;
import jakarta.transaction.Status;
import jakarta.transaction.TransactionSynchronizationRegistry;

@DisplayName("PendingWritesRegistry edge cases")
class PendingWritesRegistryEdgeCasesUnitTest {
  private static final Duration WINDOW = Duration.ofSeconds(60);

  private static TransactionSynchronizationRegistry noTransaction() {
    TransactionSynchronizationRegistry transactions =
        mock(TransactionSynchronizationRegistry.class);
    when(transactions.getTransactionStatus()).thenReturn(Status.STATUS_NO_TRANSACTION);
    return transactions;
  }

  @Test
  @DisplayName("Should work with the system clock through the injection constructor")
  void shouldUseSystemClock() {
    PendingWritesRegistry registry =
        new PendingWritesRegistry(new NoOpCache(), noTransaction(), WINDOW);

    registry.mark("role");

    assertTrue(registry.isPending("role"));
  }

  @Test
  @DisplayName("Should keep the latest local deadline when marks arrive out of order")
  void shouldKeepLatestLocalDeadline() {
    // Arrange — a clock that can move backwards
    Instant start = Instant.parse("2026-10-13T10:00:00Z");
    AtomicReference<Instant> now = new AtomicReference<>(start);
    PendingWritesRegistry registry =
        new PendingWritesRegistry(new NoOpCache(), noTransaction(), WINDOW, new Clock() {
          @Override
          public ZoneId getZone() {
            return ZoneOffset.UTC;
          }

          @Override
          public Clock withZone(ZoneId zone) {
            return this;
          }

          @Override
          public Instant instant() {
            return now.get();
          }
        });

    // Act — mark later, then mark again with an older time
    now.set(start.plusSeconds(30));
    registry.mark("role");
    now.set(start);
    registry.mark("role");

    // Assert — the later deadline (start + 90s) survives
    now.set(start.plusSeconds(75));
    assertTrue(registry.isPending("role"), "the newer deadline must not be replaced by an older");
    now.set(start.plusSeconds(91));
    assertFalse(registry.isPending("role"));

    // Act / Assert — a newer mark extends the window
    registry.mark("role");
    now.set(start.plusSeconds(140));
    assertTrue(registry.isPending("role"), "a newer deadline replaces the older one");
  }

  @Test
  @DisplayName("Should give up storing a mark when readers keep storing the empty mark")
  @SuppressWarnings("unchecked")
  void shouldGiveUpAfterRepeatedConflicts() throws ReflectiveOperationException {
    // Arrange — a cache where a reader always wins the race and stores the empty mark
    Field field = PendingWritesRegistry.class.getDeclaredField("NO_MARK");
    field.setAccessible(true);
    OffsetDateTime noMark = (OffsetDateTime) field.get(null);
    Cache cache = mock(Cache.class);
    when(cache.invalidate(any())).thenReturn(Uni.createFrom().voidItem());
    when(cache.get(any(), any())).thenReturn((Uni) Uni.createFrom().item(noMark));
    PendingWritesRegistry registry =
        new PendingWritesRegistry(cache, noTransaction(), WINDOW, Clock.systemUTC());

    // Act — try to mark the entity
    registry.mark("role");

    // Assert — every attempt was made and the entity is not pending
    verify(cache, times(5)).invalidate("role");
    assertFalse(registry.isPending("role"));
  }
}
